import { createMemo, createSignal } from "solid-js";
import { readNow } from "./read.js";

export function useLabel(source) {
  return readNow(source);
}

export function useLabelMemo(source) {
  return createMemo(() => source());
}

// An untracked read inside the package itself: a finding located here is
// the package's, and is not reported to the project.
export function Badge(props) {
  const [count] = createSignal(0);
  const seen = count();
  return <span>{props.text}{seen}</span>;
}

// A reflective write with an open source: inside the package it vetoes only
// members of objects the package creates (ADR 0273's dependency internals).
export function assignAll(target, source) {
  return Object.assign(target, source);
}

// Through another Solid package, resolved from this package's own
// node_modules.
import { readInner } from "dep-inner";
export function useInner(source) {
  return readInner(source);
}
